'use server'

import { revalidatePath } from 'next/cache'
import { cookies } from 'next/headers'

export async function toggleNotificationPreference() {
  // Get current preference from cookies (or use your preferred storage method)
  const cookieStore = await cookies()
  const currentPreference = cookieStore.get('notificationsEnabled')?.value === 'true'

  // Toggle the preference
  const newPreference = !currentPreference

  // Save the new preference (using cookies as example - you could use a database)
  cookieStore.set('notificationsEnabled', String(newPreference), {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 60 * 60 * 24 * 365, // 1 year
  })

  // Refresh the current page to show the updated preference
  revalidatePath('/')

  return newPreference
}

