import { toggleNotificationPreference } from './actions'

interface NotificationToggleProps {
  enabled: boolean
}

export function NotificationToggle({ enabled }: NotificationToggleProps) {
  return (
    <form action={toggleNotificationPreference}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
        <label htmlFor="notifications">
          Notifications: <strong>{enabled ? 'ON' : 'OFF'}</strong>
        </label>
        <button
          type="submit"
          style={{
            padding: '0.5rem 1rem',
            backgroundColor: enabled ? '#dc2626' : '#16a34a',
            color: 'white',
            border: 'none',
            borderRadius: '0.375rem',
            cursor: 'pointer',
          }}
        >
          Turn {enabled ? 'Off' : 'On'}
        </button>
      </div>
    </form>
  )
}

